}
collisions=[]
for color,p in pieces.items():
    dr,dc=p['delta']
    for r,c in p['cells']:
        rr,cc=r+dr,c+dc
        if out[rr][cc] not in (0,color): collisions.append((rr,cc,out[rr][cc],color,'color'))
        out[rr][cc]=color
for color,p in pieces.items():
    dr,dc=p['delta']
    for r,c in p['markers']:
        rr,cc=r+dr,c+dc
        if out[rr][cc] not in (0,2): collisions.append((rr,cc,out[rr][cc],color,'marker'))
        out[rr][cc]=2
print('collisions',collisions)
for row in out: print(' '.join(map(str,row)))

